INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C021', '運動後クールダウン呼吸', ARRAY['クールダウン呼吸']::text[], 'practice', '教材内の実践', '実践', '運動後に徐々に落ち着く', ARRAY['原稿では運動後に急に座り込まず、ゆっくり歩くところから始める。','呼吸が荒い間は秒数に合わせない。','少し落ち着いたら鼻から3〜4秒吸い、口から6秒吐く。','さらに落ち着いたら鼻呼吸に戻し、肩・胸・背中・脚の力を抜く。']::text[], ARRAY['P100','P120']::text[], ARRAY['K041','K042','K043','K048','K049']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C022', '横隔膜確認呼吸', '{}', 'practice', '教材内の実践', '実践', '横隔膜に伴う動きへの気づき', ARRAY['仰向けになり、片手を胸、片手をお腹に置く。','鼻から3〜4秒静かに吸い、お腹が少し広がるのを感じる。','口または鼻から4〜6秒ゆっくり吐き、お腹が自然に戻るのを感じる。']::text[], ARRAY['P101','P106','P120']::text[], ARRAY['K044','K045','K046','K047','K048']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C023', 'お腹の支え呼吸', '{}', 'practice', '教材内の実践', '実践', '体幹の支えへの気づき', ARRAY['背すじを軽く伸ばして座る。','鼻から3〜4秒吸い、お腹と背中をやさしく広げる。','口または鼻から4〜6秒吐き、お腹を薄くするよう意識する。','強く締めすぎず、息を止めずに姿勢を保つ。']::text[], ARRAY['P102','P106','P120']::text[], ARRAY['K044','K045','K046','K047','K048']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C024', 'お腹ゆるめ呼吸', '{}', 'practice', '教材内の実践', '実践', 'お腹まわりの緊張への気づき', ARRAY['楽に座るか仰向けになり、手をお腹に当てる。','鼻から3〜4秒静かに吸う。','口または鼻から6秒ほどかけて吐き、お腹の力を抜く。','みぞおち・下腹部・腰まわりをゆるめる。']::text[], ARRAY['P103','P106','P120']::text[], ARRAY['K044','K045','K046','K047','K048']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C025', '食前の整え呼吸', '{}', 'practice', '教材内の実践', '実践', '食事に入る準備', ARRAY['食べる前に姿勢を整え、肩・あご・みぞおちの力を抜く。','鼻から3〜4秒ゆっくり吸い、口または鼻から5〜6秒長く吐く。','3呼吸してから食べ始め、最初の一口をゆっくり噛む。']::text[], ARRAY['P104','P106','P120']::text[], ARRAY['K044','K045','K046','K047','K048']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C026', '食後の休息呼吸', '{}', 'practice', '教材内の実践', '実践', '食後の休息', ARRAY['食後すぐに強い運動をせず、背中を丸めすぎない楽な姿勢で座る。','お腹を締めつけない。鼻から3〜4秒静かに吸う。','口または鼻から5〜6秒ゆっくり吐く。']::text[], ARRAY['P105','P106','P120']::text[], ARRAY['K044','K045','K046','K047','K048']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[{"issue_id":"I027","rule":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C027', '本番前リセット呼吸', '{}', 'practice', '教材内の実践', '実践', '本番前の準備', ARRAY['足裏を床につけ、背すじを軽く伸ばす。','目線を一点に置き、鼻から3〜4秒吸う。','口または鼻から6秒吐き、肩・あご・手の力を抜く。','最後に自分にかける短い言葉を決める。']::text[], ARRAY['P107','P117','P227']::text[], ARRAY['K051','K052','K053','K057','K058']::text[], ARRAY['S004']::text[], false, false, '[{"variant_id":"C027-V01","label":"第14章の本番前リセット","source_passage_ids":["P117"],"steps_editorial":["背すじを伸ばし、視線を上げる。","鼻から3〜4秒吸い、口から4〜6秒吐く。","姿勢を整え、もう一度深く吸うという記載。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C027-V02","label":"14-3 プレゼンの例","source_passage_ids":["P227"],"steps_editorial":["鼻から3〜4秒吸い、口から6〜8秒吐く。","背すじを伸ばし、視線を整える。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C027-V03","label":"14-3 本番直前の例","source_passage_ids":["P227"],"steps_editorial":["鼻から3秒吸い、口から6〜8秒吐く。","短い言葉を自分に伝える。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false}]'::jsonb, '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C028', '切り替え呼吸', '{}', 'practice', '教材内の実践', '実践', '次の行動へ戻る', ARRAY['ミスや焦りに気づく。','肩を一度下げ、鼻または口から短く吸う。','口または鼻から長めに吐く。','次にやることを一つだけ決める。']::text[], ARRAY['P108','P118']::text[], ARRAY['K051','K052','K053','K057','K058']::text[], ARRAY['S004']::text[], false, false, '[{"variant_id":"C028-V01","label":"第14章の切り替え","source_passage_ids":["P118"],"steps_editorial":["軽く息を吐き切るという記載。","鼻から2〜3秒吸い、口から2〜3秒吐く。","「戻る」と心の中でつぶやく。"],"dose_source_text":"1呼吸","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false}]'::jsonb, '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C029', '動作リズム呼吸', '{}', 'practice', '教材内の実践', '概要・確認待ち', '動作と呼吸の関係を学ぶ', ARRAY['動作前に呼吸が止まっていないか確認する。','動きに合わせて吸う・吐くタイミングを考える。','力む場面で息を止めっぱなしにしない。','動作後は自然な呼吸に戻す。']::text[], ARRAY['P109','P227']::text[], ARRAY['K051','K052','K053']::text[], ARRAY['S004']::text[], false, false, '[{"variant_id":"C029-V01","label":"14-3 試合前の図","source_passage_ids":["P227"],"steps_editorial":["鼻から2〜3秒吸い、口から2〜3秒リズムよく吐くという図示。","競技や動作の準備へ移る。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"overview_only","auto_selection_allowed":false}]'::jsonb, '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C030', '力発揮呼吸', '{}', 'practice', '教材内の実践', '概要・確認待ち', '力を出す場面の呼吸を学ぶ', ARRAY['動作前に姿勢を整え、鼻または口から軽く吸う。','力を出す瞬間に短く吐く。','必要以上に息を止め続けず、動作後に呼吸を戻す。']::text[], ARRAY['P110']::text[], ARRAY['K051','K052','K053']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C031', '声の支え呼吸', '{}', 'practice', '教材内の実践', '実践', '発声の準備', ARRAY['背すじを軽く伸ばす。','鼻から3〜4秒吸い、お腹と背中が軽く広がるのを感じる。','「スー」と細く吐き、お腹を強く固めず支える。']::text[], ARRAY['P111']::text[], ARRAY['K054','K055','K086']::text[], ARRAY['S003','S004']::text[], false, false, '[]'::jsonb, '[]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C032', '発声前ウォームアップ呼吸', '{}', 'practice', '教材内の実践', '実践', '声を出す前の準備', ARRAY['背すじを軽く伸ばし、肩・あご・舌の力を抜く。','鼻から3〜4秒吸い、口から細く長く吐く。','軽くハミングし、リップロールを短く行う。','声を出す前にもう一度呼吸を整える。']::text[], ARRAY['P112','P113','P227']::text[], ARRAY['K054','K055','K086']::text[], ARRAY['S003','S004']::text[], false, false, '[{"variant_id":"C032-V01","label":"14-3 ステージの例","source_passage_ids":["P227"],"steps_editorial":["姿勢を整え、鼻から3秒吸う。","ハミングで息を流す。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false}]'::jsonb, '[{"issue_id":"I028","rule":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C033', 'ロングトーン練習', '{}', 'practice', '教材内の実践', '実践', '発声の補助練習', ARRAY['鼻から軽く吸う。','楽な高さで声を出し、声を大きくしすぎない。','息がなくなる前に終え、喉が苦しくなる前に休む。']::text[], ARRAY['P114']::text[], ARRAY['K054','K055']::text[], ARRAY['S003','S004']::text[], false, false, '[]'::jsonb, '[{"issue_id":"I028","rule":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
